/**
 * Why a light-client call failed.
 */
sealed class LightFfiException: kotlin.Exception() {
    
    /**
     * A verification, decode, or keystore failure.
     */
    class Failed(
        
        val `reason`: kotlin.String
        ) : LightFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LightFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): LightFfiException = FfiConverterTypeLightFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLightFfiError : FfiConverterRustBuffer<LightFfiException> {
    override fun read(buf: ByteBuffer): LightFfiException {
        

        return when(buf.getInt()) {
            1 -> LightFfiException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LightFfiException): ULong {
        return when(value) {
            is LightFfiException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: LightFfiException, buf: ByteBuffer) {
        when(value) {
            is LightFfiException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}
